contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(dummy >= 0);
        uint recBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint thisBefore = address(this).balance;
        uint cBefore = address(c).balance;
        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted
            && c.balances(address(this)) == 0
            && address(this).balance - thisBefore == recBefore
            && cBefore - address(c).balance == recBefore);
    }
    receive() external payable {}
}

