// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(uint256 dummy) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(dummy >= 0);
        uint256 recBefore;
        try c.balances(address(this)) returns (uint256 __r) { recBefore = __r; } catch { return; }
        uint thisBefore = address(this).balance;
        uint cBefore = address(c).balance;
        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted
            && c.balances(address(this)) == 0
            && address(this).balance - thisBefore == recBefore
            && cBefore - address(c).balance == recBefore);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
